// src/pages/ChatApp.jsx
import React, { useState, useEffect } from "react";
import axios from "axios";  // For fetching chat history (if needed)
import "./ChatApp.css";

const ChatApp = () => {
  const [messages, setMessages] = useState([]);  // Store the current chat messages
  const [chatHistory, setChatHistory] = useState([]);  // Store previous chats
  const [newMessage, setNewMessage] = useState("");  // Track input message
  const [loading, setLoading] = useState(false);  // For loading state

  // Simulating fetching chat history (you can connect this with your backend later)
  useEffect(() => {
    // Here you can fetch the previous chat history from your API or Supabase
    setChatHistory([
      { id: 1, message: "Hello, how can I help you?" },
      { id: 2, message: "I'd like some meal recommendations." },
    ]);
  }, []);

  const handleSendMessage = async () => {
    if (newMessage.trim()) {
      setLoading(true);
      const userMessage = { id: Date.now(), message: newMessage, sender: "user" };

      // Add the user's message to the messages state
      setMessages((prevMessages) => [...prevMessages, userMessage]);
      
      // Simulate a response from the chatbot (replace with actual backend call)
      const botMessage = { id: Date.now() + 1, message: "Sure! I can help you with that.", sender: "bot" };
      setMessages((prevMessages) => [...prevMessages, botMessage]);

      setNewMessage("");  // Clear the input box
      setLoading(false);  // Stop loading
    }
  };

  return (
    <div className="chat-container">
      <div className="sidebar">
        <h3>Chat History</h3>
        <ul>
          {chatHistory.map((chat) => (
            <li key={chat.id}>{chat.message}</li>
          ))}
        </ul>
      </div>
      <div className="chat-area">
        <div className="chat-messages">
          {messages.map((msg) => (
            <div key={msg.id} className={msg.sender === "user" ? "user-message" : "bot-message"}>
              {msg.message}
            </div>
          ))}
        </div>
        <div className="chat-input">
          <input
            type="text"
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            placeholder="Type a message..."
            disabled={loading}
          />
          <button onClick={handleSendMessage} disabled={loading}>
            Send
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatApp;
